-- After 15, as the agent user under the seed's revokes: what the value-free sources answer.
-- The two views hold no value column of their own.
DESCRIBE SELECT * FROM SYSIBM.COLUMNS;
DESCRIBE SELECT * FROM SYSIBM.SQLCOLUMNS;
-- SYSIBM.COLUMNS lists IBM's own objects, the ones that keep stored values among them.
SELECT VARCHAR(TABLE_SCHEMA, 8) AS TABLE_SCHEMA, VARCHAR(TABLE_NAME, 28) AS TABLE_NAME, VARCHAR(COLUMN_NAME, 10) AS COLUMN_NAME FROM SYSIBM.COLUMNS WHERE COLUMN_NAME IN ('COLVALUE', 'HIGH2KEY', 'LOW2KEY') ORDER BY 1, 2, 3;
-- The code page, without SYSCAT.COLUMNS.
SELECT VARCHAR(CHARACTER_SET_NAME, 20) AS CHARACTER_SET_NAME FROM SYSIBM.COLUMNS WHERE TABLE_SCHEMA = 'SYSIBM' AND TABLE_NAME = 'SYSDUMMY1' AND COLUMN_NAME = 'IBMREQD';
SELECT VARCHAR(COLUMN_NAME, 10) AS COLUMN_NAME, VARCHAR(CHARACTER_SET_NAME, 20) AS CHARACTER_SET_NAME FROM SYSIBM.COLUMNS WHERE TABLE_SCHEMA = 'APP' AND TABLE_NAME = 'LIBREDB_VF_TYPES' ORDER BY ORDINAL_POSITION;
VALUES HEX(U&'\00E9');
-- Every column of the fixture table, a table the user may not read, a view, and APP.ORDERS, with the defaults.
SELECT VARCHAR(TABLE_NAME, 18) AS TABLE_NAME, VARCHAR(COLUMN_NAME, 11) AS COLUMN_NAME, VARCHAR(DATA_TYPE, 34) AS DATA_TYPE, CHARACTER_MAXIMUM_LENGTH AS CML, CHARACTER_OCTET_LENGTH AS COL, NUMERIC_PRECISION AS NP, NUMERIC_SCALE AS NS, DATETIME_PRECISION AS DP, VARCHAR(IS_NULLABLE, 3) AS NUL, ORDINAL_POSITION AS POS, VARCHAR(COLUMN_DEFAULT, 30) AS COLUMN_DEFAULT, LENGTH(COLUMN_DEFAULT) AS DL FROM SYSIBM.COLUMNS WHERE TABLE_SCHEMA = 'APP' AND TABLE_NAME IN ('LIBREDB_VF_TYPES', 'LIBREDB_VF_HIDDEN', 'LIBREDB_VF_VIEW', 'ORDERS') ORDER BY 1, POS;
-- A distinct-type column: SYSIBM.COLUMNS names its type in UDT_SCHEMA and UDT_NAME.
SELECT VARCHAR(TABLE_NAME, 18) AS TABLE_NAME, VARCHAR(COLUMN_NAME, 10) AS COLUMN_NAME, VARCHAR(DATA_TYPE, 14) AS DATA_TYPE, VARCHAR(UDT_SCHEMA, 8) AS UDT_SCHEMA, VARCHAR(UDT_NAME, 20) AS UDT_NAME, HEX(UDT_NAME) AS UDT_NAME_HEX FROM SYSIBM.COLUMNS WHERE TABLE_SCHEMA = 'APP' AND TABLE_NAME = 'LIBREDB_VF_TYPES' AND UDT_NAME IS NOT NULL;
SELECT VARCHAR(TABLE_NAME, 18) AS TABLE_NAME, VARCHAR(COLUMN_NAME, 10) AS COLUMN_NAME, VARCHAR(TYPE_NAME, 26) AS TYPE_NAME, COLUMN_SIZE, DECIMAL_DIGITS, NULLABLE, VARCHAR(COLUMN_DEF, 30) AS COLUMN_DEF FROM SYSIBM.SQLCOLUMNS WHERE TABLE_SCHEM = 'APP' AND TABLE_NAME IN ('LIBREDB_VF_TYPES', 'LIBREDB_VF_HIDDEN') ORDER BY 1, ORDINAL_POSITION;
-- The primary key without SYSCAT.COLUMNS.
SELECT VARCHAR(k.TABNAME, 18) AS TABNAME, VARCHAR(k.COLNAME, 10) AS COLNAME, k.COLSEQ FROM SYSCAT.KEYCOLUSE k JOIN SYSCAT.TABCONST c ON c.CONSTNAME = k.CONSTNAME AND c.TABSCHEMA = k.TABSCHEMA AND c.TABNAME = k.TABNAME WHERE c.TYPE = 'P' AND k.TABSCHEMA = 'APP' AND k.TABNAME IN ('LIBREDB_VF_TYPES', 'LIBREDB_VF_HIDDEN', 'ORDERS') ORDER BY 1, 3;
-- A zero-row describe: of a table the user may read, and of one it may not.
DESCRIBE SELECT * FROM APP.LIBREDB_VF_TYPES WHERE 1 = 0;
SELECT * FROM APP.LIBREDB_VF_HIDDEN WHERE 1 = 0;
